const express = require('express');
const crypto = require('crypto');
const argon2 = require('argon2');

class SessionStore {
  constructor() {
    this.sessions = new Map();
    this.revocationList = new Set();
    this.pendingRevocations = new Map();
  }

  createSession(userId, roles) {
    const token = crypto.randomBytes(32).toString('hex');
    const session = {
      userId,
      roles: [...roles],
      createdAt: Date.now(),
      lastAccess: Date.now(),
      token
    };
    this.sessions.set(token, session);
    return token;
  }

  // Phase 1: Validate token exists and is not expired
  validateToken(token) {
    if (typeof token !== 'string' || token.length !== 64) return null;
    if (this.revocationList.has(token)) return null;
    const session = this.sessions.get(token);
    if (!session) return null;
    if (Date.now() - session.createdAt > 3600000) {
      this.sessions.delete(token);
      return null;
    }
    return { valid: true, userId: session.userId };
  }

  // Phase 2: Fetch full session with roles for authorization
  getSessionRoles(token) {
    const session = this.sessions.get(token);
    if (!session) return null;
    session.lastAccess = Date.now();
    return { userId: session.userId, roles: session.roles };
  }

  revokeSession(token) {
    this.revocationList.add(token);
    // Schedule actual deletion for cleanup
    this.pendingRevocations.set(token, setTimeout(() => {
      this.sessions.delete(token);
      this.pendingRevocations.delete(token);
    }, 100));
  }

  revokeAllUserSessions(userId) {
    for (const [token, session] of this.sessions.entries()) {
      if (session.userId === userId) {
        this.revokeSession(token);
      }
    }
  }
}

class ResourceAccessControl {
  constructor(sessionStore) {
    this.store = sessionStore;
    this.resourceOwners = new Map();
    this.accessLog = [];
  }

  registerResource(resourceId, ownerId) {
    this.resourceOwners.set(resourceId, ownerId);
  }

  // Two-phase authorization check
  async authorizeAccess(token, resourceId, requiredRole) {
    // Phase 1: Quick token validation (checks revocation list)
    const validation = this.store.validateToken(token);
    if (!validation || !validation.valid) {
      return { authorized: false, reason: 'invalid_token' };
    }

    // Simulate async operation (audit log write, rate limit check, etc.)
    await this._performAuditCheck(validation.userId, resourceId);

    // Phase 2: Fetch roles for authorization decision
    const sessionData = this.store.getSessionRoles(token);
    if (!sessionData) {
      return { authorized: false, reason: 'session_expired' };
    }

    const owner = this.resourceOwners.get(resourceId);
    if (!owner) {
      return { authorized: false, reason: 'resource_not_found' };
    }

    // Check ownership OR role-based access
    if (sessionData.userId === owner) {
      return { authorized: true, userId: sessionData.userId, via: 'ownership' };
    }

    if (sessionData.roles.includes(requiredRole)) {
      return { authorized: true, userId: sessionData.userId, via: 'role' };
    }

    return { authorized: false, reason: 'insufficient_privileges' };
  }

  async _performAuditCheck(userId, resourceId) {
    // Simulates async I/O - writes audit entry
    return new Promise(resolve => {
      setImmediate(() => {
        this.accessLog.push({
          userId,
          resourceId,
          timestamp: Date.now()
        });
        resolve();
      });
    });
  }
}

const app = express();
app.use(express.json());

const sessionStore = new SessionStore();
const acl = new ResourceAccessControl(sessionStore);

// Setup some test data
sessionStore.createSession('admin1', ['admin', 'user']);
acl.registerResource('secret-doc-1', 'admin1');
acl.registerResource('public-doc-1', 'user1');

app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }
  // In production, verify against stored argon2 hash
  // const valid = await argon2.verify(storedHash, password);
  const roles = username === 'admin' ? ['admin', 'user'] : ['user'];
  const token = sessionStore.createSession(username, roles);
  res.json({ token });
});

app.get('/api/resource/:id', async (req, res) => {
  const token = req.headers['x-session-token'];
  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  const result = await acl.authorizeAccess(token, req.params.id, 'admin');
  if (!result.authorized) {
    return res.status(403).json({ error: result.reason });
  }

  res.json({ data: `Content of ${req.params.id}`, accessedBy: result.userId, via: result.via });
});

app.post('/api/admin/revoke-user', async (req, res) => {
  const token = req.headers['x-session-token'];
  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  const validation = sessionStore.validateToken(token);
  if (!validation) {
    return res.status(401).json({ error: 'Invalid session' });
  }

  const session = sessionStore.getSessionRoles(token);
  if (!session || !session.roles.includes('admin')) {
    return res.status(403).json({ error: 'Admin required' });
  }

  const { targetUser } = req.body;
  if (!targetUser || typeof targetUser !== 'string') {
    return res.status(400).json({ error: 'Invalid target user' });
  }

  sessionStore.revokeAllUserSessions(targetUser);
  res.json({ success: true, message: `All sessions for ${targetUser} revoked` });
});

app.listen(3000);
module.exports = { app, sessionStore, acl, SessionStore, ResourceAccessControl };
